export async function loadWorldImage(url,{fetcher=globalThis.fetch,createBitmap=globalThis.createImageBitmap,createImage=()=>new Image}={}){if(typeof createBitmap=="function"){const response=await fetcher(url);if(!response.ok)throw new Error(response.status+" "+url);const blob=await response.blob();try{return{image:await createBitmap(blob,{imageOrientation:"flipY",premultiplyAlpha:"none",colorSpaceConversion:"none"}),flipY:!1}}catch{}}return new Promise((resolve,reject)=>{const image=createImage();image.crossOrigin="anonymous",image.decoding="async";const finish=()=>{image.onload=image.onerror=null};image.onload=()=>{finish(),resolve({image,flipY:!0})},image.onerror=()=>{finish(),reject(new Error("Image could not decode: "+url))},image.src=url})}